\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
SEG ::= segA | segB
\end{zed}

\begin{zed}
RAWSEG ::= rsSeg \ldata SEG \rdata | rsEmpty | rsDot
\end{zed}

\begin{zed}
PATSEG ::= litSeg \ldata SEG \rdata | wildRestSeg
\end{zed}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{axdef}
unwrap : RAWSEG \pfun SEG
\where
\forall s : SEG @ unwrap(rsSeg(s)) = s
\end{axdef}

\begin{axdef}
SplitSegments : \seq RAWSEG \fun \seq SEG
\where
\forall raw : \seq RAWSEG @ SplitSegments(raw) = squash(raw \comp unwrap)
\end{axdef}

\begin{axdef}
Absolute : \seq RAWSEG \fun ZBOOL
\where
\forall raw : \seq RAWSEG @
  Absolute(raw) = (\IF \# raw > 0 \land raw(1) = rsEmpty \THEN ztrue \ELSE zfalse)
\end{axdef}

\begin{axdef}
Stringify : PATSEG \fun SEG
\where
Stringify(wildRestSeg) = segA \\
\forall s : SEG @ Stringify(litSeg(s)) = s
\end{axdef}

\begin{axdef}
LiteralSegs : \seq PATSEG \fun \seq SEG
\where
\forall p : \seq PATSEG @ LiteralSegs(p) = p \comp Stringify
\end{axdef}

\begin{schema}{Store}
open : \nat \pfun SEG
\where
\dom open \subseteq 1 \upto 2
\end{schema}

\begin{schema}{Release}
\Delta Store \\
slot? : \nat
\where
slot? \in \dom open \\
open' = \{ slot? \} \ndres open
\end{schema}

\end{document}

%
% vaib-decoupled.tex -- scratch, not committed.
%
% Decoupled reachability demonstration for ethos-vaib: splitSegments
% drops the leading empty segment an absolute path produces, so an
% absolute file target is admitted by a relative glob entry. Built
% independently of docs/spec-writeset-admission.tex's own checked
% namespace, per the errata technique in spec-mission-lifecycle.tex
% Section "Validation": the safety property (absolute paths must not
% be swallowed by a relative entry) must not be baked into the type
% FileRaw is checked against, or the buggy operation becomes
% unsatisfiable rather than reachable.
%
\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
SEG ::= segDocs | segXmd
\end{zed}

\begin{zed}
RAWSEG ::= rsSeg \ldata SEG \rdata | rsEmpty | rsDot
\end{zed}

\begin{zed}
PATSEG ::= litSeg \ldata SEG \rdata | wildRestSeg
\end{zed}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{axdef}
unwrap : RAWSEG \pfun SEG
\where
\forall s : SEG @ unwrap(rsSeg(s)) = s
\end{axdef}

\begin{axdef}
SplitSegments : \seq RAWSEG \fun \seq SEG
\where
\forall raw : \seq RAWSEG @ SplitSegments(raw) = squash(raw \comp unwrap)
\end{axdef}

\begin{axdef}
Absolute : \seq RAWSEG \fun ZBOOL
\where
\forall raw : \seq RAWSEG @
  Absolute(raw) = (\IF \# raw > 0 \land raw(1) = rsEmpty \THEN ztrue \ELSE zfalse)
\end{axdef}

\begin{axdef}
Contains : \seq PATSEG \rel \seq SEG
\where
\forall es : \seq PATSEG; fs : \seq SEG @
  (es \mapsto fs \in Contains) \iff
    (\# es = 0)
    \lor (\# es > 0 \land es(\# es) = wildRestSeg
          \land (\# es - 1) \leq \# fs
          \land (\forall i : 1 \upto (\# es - 1) @ es(i) = litSeg(fs(i))))
    \lor (\# es > 0 \land es(\# es) \neq wildRestSeg
          \land \# es \leq \# fs
          \land (\forall i : 1 \upto \# es @ es(i) = litSeg(fs(i))))
\end{axdef}

\begin{axdef}
witnessPattern : \seq PATSEG
\where
witnessPattern = \langle litSeg(segDocs), wildRestSeg \rangle
\end{axdef}

\begin{schema}{FileRaw}
raw : \seq RAWSEG
\where
\# raw \leq 2
\end{schema}

\begin{schema}{Init}
FileRaw'
\end{schema}

\begin{schema}{Idle}
\Xi FileRaw
\where
\lnot (Absolute(raw) = ztrue \land (witnessPattern \mapsto SplitSegments(raw) \in Contains))
\end{schema}

\end{document}

